def compute(vars):
    operating_leases = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    ratio = operating_leases / total_obligations
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "operating_leases": operating_leases,
            "total_obligations": total_obligations,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
